            "title": "Do guia de onda à porta da sala",
            "body": "No acelerador linear, micro-ondas aceleram elétrons num guia de onda. Ao atingir um alvo de metal pesado, eles geram raios X de alta energia, e o feixe sai conformado. A radiação lesa o DNA, inclusive por radicais reativos formados a partir da água. Os cinco Rs nomeiam fatores biológicos da resposta ao tratamento fracionado. A proteção soma barreiras: paredes de chumbo e concreto, comando fora da sala, intertravamento na porta e botões de emergência. Acionado um dispositivo, a irradiação para na hora e só recomeça pelo painel. Com fonte selada, ela se recolhe ao cabeçote, inclusive em falta de energia.",
